I am writing code to update a 2D array until the maximum difference is below a certain threshold. I wrote the serial code and it works fine. I am now having issues parallelizing the code using OpenMP. Below is the section where it seems to hang if I set the number of threads to be 2. (Note: I am still learning OpenMP). float max_diff = 1.0;
    while (max_diff >= 1e-4)
    {
        max_diff = 0.0; // reset max_diff on each iteration
#pragma omp parallel private(i, j) shared(n, w, w_new)
        {
#pragma omp for reduction(max : max_diff)
            for (i = 1; i < n - 1; i++) // loops from 1 till n - 1 to ensure no out of bounds in the max_diff update
            {
                for (j = 1; j < n - 1; j++)
                {
                    w_new[i][j] = (w[i + 1][j] + w[i - 1][j] + w[i][j + 1] + w[i][j - 1]) / 4.0;
                    max_diff = fmax(max_diff, fabs(w_new[i][j] - w[i][j])); // returns either max_diff or the difference between w_new and original w array.
                }
            }
       }
        float **temp = w;
        w = w_new;
        w_new = temp;
    } I tried different approaches but it still seems to deadlock here for 2 threads. It runs when setting the threads to be 4 but it is slower than the serial execution or execution with 1 thread. I can provide the full script if requested. I have spent days at this and I can't find a way to parallelize it properly. Please help! EDIT 1: I have updated the code slightly. I added a print statement to print the values of max_diff along with the thread number to check for synchronisation. I also added #pragma omp single at the end so no race conditions occur when copying the array. EDIT 2: Further fixed code to my most updated version. Moved the reduction clause to the loop region and removed omp single clause and put pointer swapping outside of the parallel region. Still running slow with 2 threads+. EDIT 3: Including full source code below. Compiled with gcc -o steadyState steady_state.c -fopenmp -lm . Running on a VM with dual core Intel(R) Xeon(R) CPU E5-2666 v3 @ 2.90 GHz. gcc version 4.8.5 (Red Hat 4.8.5-44). 4 GB of RAM also. #include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <omp.h>
#include <time.h>

int main(int argc, char **argv)
{

    printf("Running...\n");
    FILE *outFile;
    outFile = fopen("2darray.txt", "w");
    float **w;
    int n = 100;
    int nthreads;

    if (argc != 2)
    {
        printf("Wrong number of arguments!\n");
        printf("Correct usage: %s nthreads\n", argv[0]);
        exit(1);
    }

    nthreads = atoi(argv[1]);
    omp_set_num_threads(nthreads);
    printf("Number of threads used: %d\n", nthreads);

    // initialise 2D array 100 x 100
    w = (float **)malloc(n * sizeof(float *));

    int i, j;
    // allocate memory for each row
    for (i = 0; i < n; i++)
    {
        w[i] = (float *)malloc(n * sizeof(float));
    }

    /* initialise array with given values
    first row: 0.0
    last row: 100.
    first column: 100.
    last column: 100
    all other elements: 75.
    */
#pragma omp parallel for private(i, j) shared(n, w)
    for (i = 0; i < n; i++)
    {
        for (j = 0; j < n; j++)
        {
            if (i == 0 && j > 0 && j < n - 1) // first row
            {
                w[i][j] = 0.0;
            }
            else if (i == n - 1) // last row
            {
                w[i][j] = 100.0;
            }
            else if (j == 0) // first column
            {
                w[i][j] = 100.0;
            }
            else if (j == n - 1) // last column
            {
                w[i][j] = 100.0;
            }
            else // all other elements
            {
                w[i][j] = 75.0;
            }
        }
    }
    printf("Initial array set!\n");

    /* update interior values */
    float **w_new; // make new array from copy of original
    w_new = (float **)malloc(n * sizeof(float *));
    for (i = 0; i < n; i++)
    {
        w_new[i] = (float *)malloc(n * sizeof(float));
    }

    for (i = 0; i < n; i++)
    {
        for (j = 0; j < n; j++)
        {
            w_new[i][j] = w[i][j];
        }
    }
    printf("New array copied! Updating new array...\n");

    double start = omp_get_wtime();
    float max_diff = 1.0;
    int iterations = 0;
    while (max_diff >= 1e-4)
    {
        max_diff = 0.0; // reset max_diff on each iteration
#pragma omp parallel private(i, j) shared(n, w, w_new)
        {
#pragma omp for reduction(max : max_diff)
            for (i = 1; i < n - 1; i++) // loops from 1 till n - 1 to ensure no out of bounds in the max_diff update
            {
                for (j = 1; j < n - 1; j++)
                {
                    w_new[i][j] = (w[i + 1][j] + w[i - 1][j] + w[i][j + 1] + w[i][j - 1]) / 4.0;
                    max_diff = fmax(max_diff, fabs(w_new[i][j] - w[i][j])); // returns either max_diff or the difference between w_new and original w array.
                }
            }
            //printf("max_diff: %.3f\thread: %d", max_diff, omp_get_thread_num()); //optional print statement for debugging

        }
        // swap pointers
        float **temp = w;
        w = w_new;
        w_new = temp;

        iterations++;
    }
    printf("Maximum difference now less than 1e-4! Stopping.\n");
    double end = omp_get_wtime();
    double time = end - start;
    printf("Time taken to reach tolerance: %.12f s\n", time);

    // print array
    for (i = 0; i < n; i++)
    {
        for (j = 0; j < n; j++)
        {
            fprintf(outFile, "%.1f  ", w[i][j]);
        }
        fprintf(outFile, "\n");
    }
    fclose(outFile);

    for (i = 0; i < n; i++)
    {
        free(w[i]);
        free(w_new[i]);
    }
    free(w);
    free(w_new);
    return 0;
}

I'm trying to optimise the following parallel execution to use threadprivate variables as the Eigen Vector evalInput could easily be thread_local and shared between iterations/tasks within a thread: #pragma omp parallel for schedule(dynamic)
for (int j = 0; j < input.rows(); ++j)
{
    Eigen::VectorXf evalInput = input;
    // Modify one entry of evalInput, then restore after evaluating
    output.col(j) = factors * evalInput;
} I tried to get evalInput to be shared per-thread with threadprivate and copyin, but even the most basic example does not work for me: static Eigen::VectorXf evalInput = input;
#pragma omp threadprivate(evalInput)

#pragma omp parallel for schedule(dynamic) copyin(evalInput)
for (int j = 0; j < input.rows(); ++j)
{
    evalInput[j] += 1.0;
    output.col(j) = factors * evalInput;
    evalInput[j] = input[j];
} Depending on the circumstances, I get the error error: ‘threadprivate’ ‘evalInput’ has incomplete type or error: ‘evalInput’ declared ‘threadprivate’ after first use (gcc 13.2.1). However, notably, it does work in clang. I prepared four simplified test cases, each changing one thing to the last, and not using Eigen, but simple vectors (so ignore that there is no point in using threadprivate here): parallelBasic being the basic implementation to optimise (as an example, not what I actually want to optimise) using templated Scalar. parallelOpt adds the threadprivate variable, yielding the incomplete type error. parallelOptFloat then drops the Scalar template, yielding in the first use error. parallelVar finally adds a random, unused templated parameter, and for some reason DOES compile. It can be compiled with g++ -o main -c main.cpp -Iinclude -fopenmp -lgomp and it will fail, but when compiled with clang++ it does work: #include <omp.h>

#include <vector>

template<typename Scalar>
void parallelBasic(const std::vector<Scalar> &input, const std::vector<Scalar> &factors, std::vector<Scalar> &output)
{
    #pragma omp parallel for schedule(dynamic)
    for (int j = 0; j < input.size(); ++j)
    {
        output[j] = factors[j] * input[j];
    }
}

template<typename Scalar>
void parallelOpt(const std::vector<Scalar> &input, const std::vector<Scalar> &factors, std::vector<Scalar> &output)
{ // Does not work, "‘threadprivate’ ‘evalInput’ has incomplete type"
    static std::vector<Scalar> evalInput;
    #pragma omp threadprivate(evalInput)
    evalInput = input;

    #pragma omp parallel for schedule(dynamic) copyin(evalInput)
    for (int j = 0; j < input.size(); ++j)
    {
        output[j] = factors[j] * evalInput[j];
    }
}

void parallelOptFloat(const std::vector<float> &input, const std::vector<float> &factors, std::vector<float> &output)
{ // Removed templated Scalar, also does not work, "‘evalInput’ declared ‘threadprivate’ after first use"
    static std::vector<float> evalInput;
    #pragma omp threadprivate(evalInput)
    evalInput = input;

    #pragma omp parallel for schedule(dynamic) copyin(evalInput)
    for (int j = 0; j < input.size(); ++j)
    {
        output[j] = factors[j] * evalInput[j];
    }
}

template<typename Scalar>
void parallelVar(const std::vector<float> &input, const std::vector<float> &factors, std::vector<float> &output, Scalar value)
{ // Works, just added unused parameter
    static std::vector<float> evalInput;
    #pragma omp threadprivate(evalInput)
    evalInput = input;

    #pragma omp parallel for schedule(dynamic) copyin(evalInput)
    for (int j = 0; j < input.size(); ++j)
    {
        output[j] = factors[j] * evalInput[j];
    }
}

int main ()
{
    omp_set_dynamic(0);

    std::vector<float> input(100), factors(100), output(100);

    parallelBasic<float>(input, factors, output);

    //parallelOpt<float>(input, factors, output);

    //parallelOptFloat(input, factors, output);

    parallelVar(input, factors, output, 1);

    return 0;
} Thank you for any help.

I'm new to programming and trying to learn the concept of multiprocessing. To try some things out I've created a C++ program that processes and analyzes data. The program reads data from a JSON file, calculates a new value for the data class, applies a filter based on those values, and then sorts and outputs the data. I've employed OpenMP for parallel processing to optimize performance. However, I feel there might be further optimizations possible, either in the way I'm handling data, sorting it, or in the parallel processing approach. I am looking for suggestions to make this code more efficient. Here's the code: #include <iostream>
#include <iomanip>
#include <fstream>
#include <array>
#include <algorithm>
#include "json.hpp"
#include "sha1.hpp"
#include <omp.h>

using namespace std;
using json = nlohmann::json;
const int DataSize = 23;

class EcologyData
{
    double ecologyScore;

public:
    EcologyData()
    {
        this->ecologyScore = 0;
    }
    EcologyData(double value)
    {
        this->ecologyScore = value;
    }
    double getEcologyScore() const
    {
        return this->ecologyScore;
    }
    void setEcologyScore(double value)
    {
        this->ecologyScore = value;
    }
};

struct Car {
    string make;
    int year;
    double mpg;
    string hashCode;
    EcologyData ecologyScore;
};

double calculateEcologyScore(const Car& car) {
    return car.year * car.mpg;
}

bool meetsFilterCriteria(Car& car, double filterThreshold) {
    return car.ecologyScore.getEcologyScore() > filterThreshold;
}

class ResultMonitor
{
    array<Car, DataSize> cars;
    int currentSize = 0;

public:
    array<Car, DataSize> getCars()
    {
        return cars;
    }


    void addSorted(Car newCar)
    {
#pragma omp critical
        {
            if (currentSize == 0)
            {
                cars[currentSize] = newCar;
                currentSize++;
            }
            else
            {
                cars[currentSize] = newCar;
                currentSize++;

                for (int i = 0; i < currentSize - 1; i++)
                {
                    for (int j = 0; j < currentSize - i - 1; j++)
                    {
                        if (cars[j].ecologyScore.getEcologyScore() > cars[j + 1].ecologyScore.getEcologyScore())
                        {
                            Car temp = cars[j];
                            cars[j] = cars[j + 1];
                            cars[j + 1] = temp;
                        }
                    }
                }
            }
        }
    }

    int getCount()
    {
        return currentSize;
    }
};

ResultMonitor resultMonitor;
array<Car, DataSize> cars;

double processCarData(Car& car, int threadId)
{
    SHA1 sha1;
    sha1.update(car.make);
    sha1.update(std::to_string(car.year));
    sha1.update(std::to_string(car.mpg));
    car.hashCode = sha1.final();

    car.ecologyScore = calculateEcologyScore(car);

    int filterCriteriaValue = 50000;

    if (meetsFilterCriteria(car, filterCriteriaValue))
    {
        resultMonitor.addSorted(car);
        return car.year + car.mpg;
    }
    return 0;
}

class OutputPrinter
{
private:
    static void printDashToConsole(int count)
    {
        for (int i = 0; i < count; i++)
        {
            cout << "-";
        }
        cout << endl;
    }

    static void printDash(ofstream& output, int size)
    {
        for (int i = 0; i < size; i++)
        {
            output << "-";
        }
        output << endl;
    }
public:
    static void printInitialDataConsole(const array<Car, DataSize>& cars)
    {
        int dashCount = 51;

        cout << "Duomenu failo duomenys:" << endl;
        printDashToConsole(dashCount);

        cout << left << setw(23) << "| Make" << left << setw(12) << "| Year " << left << setw(15) << "| Ecology " << "|" << endl;
        printDashToConsole(dashCount);

        for (const auto& car : cars)
        {
            cout << "| " << left << setw(20) << car.make
                << " | " << left << setw(9) << car.year << " | "
                << left << setw(12) << car.mpg << " | " << endl;
        }

        printDashToConsole(dashCount);
    }

    static void printResults(const array<Car, DataSize>& sortedCars, int count, string outputFile)
    {
        ofstream output(outputFile, ios_base::app);
        int dashCount = 136;
        output << "Rezultatai" << endl;
        printDash(output, dashCount);
        output << left << setw(23) << "| Make" << left << setw(23) << "| Year " << left << setw(22) << "| Ecology " 
            << left << setw(23) << " | Ecology score" << left << setw(44) << " | HashCode" << "|" << endl;
        printDash(output, dashCount);

        for (int i = 0; i < count; i++)
        {
            output << "| " << left << setw(20) << sortedCars[i].make
                << " | " << left << setw(20) << sortedCars[i].year << " | "
                << left << setw(20) << sortedCars[i].mpg << " | "
                << left << setw(20) << sortedCars[i].ecologyScore.getEcologyScore() << " | "
                << left << setw(40) << sortedCars[i].hashCode << " |" << endl;
        }

        printDash(output, dashCount);
        output.close();
    }

    static void printInitialData(const array<Car, DataSize>& cars, string outputFile)
    {
        ofstream output(outputFile);
        int dashCount = 51;

        output << "Duomenu failo duomenys:" << endl;
        printDash(output, dashCount);

        output << left << setw(23) << "| Make" << left << setw(12) << "| Year " << left << setw(15) << "| Ecology " << "|" << endl;
        printDash(output, dashCount);

        for (const auto& car : cars)
        {
            output << "| " << left << setw(20) << car.make
                << " | " << left << setw(9) << car.year << " | "
                << left << setw(12) << car.mpg << " | " << endl;
        }
        printDash(output, dashCount);

        output << endl;
        output.close();
    }
};

int main()
{;
    ifstream inputFile("data.json");
    json jsonCars;
    inputFile >> jsonCars;

    int i = 0;
    for (const auto& carData : jsonCars)
    {
        if (i < DataSize) {
            Car car;
            car.make = carData["make"];
            car.year = carData["year"];
            car.mpg = carData["mpg"];
            cars[i++] = car;
        }
        else {
            break;
        }
    }
    OutputPrinter::printInitialDataConsole(cars);
    OutputPrinter::printInitialData(cars, "results.txt");

    int size = cars.size();
    int threadCount = size / 4;

    auto ValuesForSum = new double[DataSize];
    int ValuesForSumIndex = 0;
    double sum = 0;

#pragma omp parallel for num_threads(threadCount) reduction(+:sum)
    for (int i = 0; i < threadCount; i++)
    {
        auto totalThreads = omp_get_num_threads();
        int threadNumber = omp_get_thread_num();
        int chunkSize = size / 4;
        int leftower_chunks = size % 4;
        int start = threadNumber * chunkSize;
        int end;
        if (threadNumber == totalThreads - 1) {
            end = size;
        }
        else {
            end = start + chunkSize;
        }
        for (int j = start; j < end; j++)
        {
            Car car = cars[j];
            ValuesForSum[ValuesForSumIndex++] = processCarData(car, threadNumber);
            sum = accumulate(ValuesForSum + start, ValuesForSum + end, 0,
                [](double acc, double curr) { return acc + curr; });        }
    }
    cout << "Float ir int suma: " << sum << endl;

    array<Car, DataSize> sortedCars;
    sortedCars = resultMonitor.getCars();

    OutputPrinter::printResults(sortedCars, resultMonitor.getCount(), "rezultatai.txt");
    return 0;
}

