parallel time:4.555 serial time:0.0071298 Below are some code snippets, here is the complete code . Partition: int partition(vector<int> &data, int p, int r){
    int pivot = data[p];
    int left = p;
    int right = r;
    while (left < right){
        while (left < r && data[left] <= pivot) ++left;
        while (right >= 0 && data[right] > pivot) --right;
        if (left < right && left <r && right >= 0)
        {
            std::swap(data[left], data[right]);
        }
    }

    if (left < right && left <r && right >= 0)
    {
        std::swap(data[left], data[right]);
    }
    data[p] = data[right];
    data[right] = pivot;
    return right;
} Parallel Quicksort: void ParallelQuickSort (vector<int> &dataList,  int nLower, int nUpper)                                                                                             
{
    if (nLower < nUpper)
    {
        int nSplit = partition (dataList, nLower, nUpper);
        omp_set_num_threads(2);
        #pragma omp parallel sections
        {
