I've created an implementation of the naive N-body problem with N^2 time complexity using c++ and I've tried to parallelize it using OpenMP. For example, running the program 5 times with 1000 bodies, 100 timesteps, I get the median time taken to execute at 14.06565 seconds. Then running this program with 2 threads with same parameters, I get the median of 6.25671 seconds which is very good (almost even too good since the performance has more than doubled). Although when I try to run the program with 3 threads, I get the median of 6.90014 seconds, which isn't an improvement at all compared to running it with 2 threads. And same thing for when running with 4 threads, I get the median of 7.66918 seconds, and going beyond 4 threads nothing seems to improve. Now I'm running the program on an AMD ryzen 5 3600 CPU which has more than enough cores to handle more than 4 threads running simultaneously. So I can't pinpoint what is wrong with my code, since previously working with OpenMP, I've never witnessed that only running 2 threads on a program yields the best possible results and more than doubles the speedup. I feel that something may be wrong with my code and I can't pinpoint what exactly, and any help is appreciated. I've tried modifying/changing the scheduling clause for the OMP directives, temporarily removed variables/arrays which may have false sharing (the 2d vector f is a potential candidate for this), and even commented out the moveBodies-function, with the performance being exactly the same. It seems that the issue seems to lie at calculateForces function, perhaps load balancing? #include <iostream>
#include <cmath>
#include <vector>
#include <chrono>
#include <omp.h>

using namespace std;

struct point{
    double x=0;
    double y=0;

    point(double x_, double y_) : x(x_), y(y_) {}

    point() : x(0), y(0) {}
};

double G = 6.67e-11; //gravity

#define DT 0.01
#define SIZE 9e7


//Generate random double
double fRand(double fMin, double fMax) {
    double f = (double)rand() / RAND_MAX;
    return fMin + f * (fMax - fMin);
}


//calculate total force for every pair of bodies
void calculateForces(vector<point>& p, vector<vector<point>>& f, vector<double>& m, const int& n){
    double distance;
    double magnitude;
    point direction;

    #pragma omp parallel for schedule(static, 1) //Stripes evenly distributed
    for (int i=0; i<n-1;i++){
        int id = omp_get_thread_num();
        for (int j = i+1; j < n; j++) {
            distance =  sqrt(pow((p[i].x - p[j].x),2) + pow((p[i].y - p[j].y),2));
            magnitude = (G*m[i]*m[j]) / pow(distance,2);
            direction.x = p[j].x-p[i].x; 
            direction.y = p[j].y-p[i].y;

            f[id][i].x = f[id][i].x + magnitude*direction.x/distance;

            f[id][j].x = f[id][j].x - magnitude*direction.x/distance;

            f[id][i].y = f[id][i].y + magnitude*direction.y/distance;

            f[id][j].y = f[id][j].y - magnitude*direction.y/distance;
        }
    }
}

//calculate new velocity and position for each body
void moveBodies(vector<point>& p, vector<vector<point>>& f, vector<double>& m, vector<point>& v, const int& n) {
    point deltav; // dv=f/m * DT
    point deltap; // dp=(v+dv/2) * DT

    #pragma omp parallel for private(deltav, deltap) schedule(static, 1)
    for (int i = 0; i < n; i++) {
        point force;
        for (int k = 0; k < omp_get_num_threads(); k++) {
            force.x += f[k][i].x; f[k][i].x = 0;
            force.y += f[k][i].y; f[k][i].y = 0;
        }
        deltav.x = force.x/m[i] * DT;
        deltav.y = force.y/m[i] * DT;
        deltap.x = (v[i].x + deltav.x/2) * DT;
        deltap.y = (v[i].y + deltav.y/2) * DT;
        v[i].x = v[i].x + deltav.x;
        v[i].y = v[i].y + deltav.y;
        p[i].x = p[i].x + deltap.x;
        p[i].y = p[i].y + deltap.y;
        force.x = force.y = 0.0; // reset force vector
    }
}

int main(int argc, char** argv)
{

    if (argc != 4) {
        cout << "Incorrect amount of arguments!" << endl;
        return 0;
    }

    srand(time(NULL));

    int gnumBodies = atoi(argv[1]);
    int numSteps = atoi(argv[2]);
    int nThreads = atoi(argv[3]);

    cout << "number of bodies: " << gnumBodies << endl;
    cout << "number of timesteps: " << numSteps << endl;

    omp_set_num_threads(nThreads);

    vector<point> p; //Position
    vector<point> v; //velocity
    vector<vector<point>> f(nThreads, vector<point>(gnumBodies)); //force
    vector<double> m; //mass

    for (int i = 0; i < gnumBodies; i++) {
        p.push_back(point(fRand(0, SIZE), fRand(0, SIZE)));
        v.push_back(point(0,0));
        m.push_back(fRand(6e22, 2e30));
    }

    auto start = omp_get_wtime();
    for (int i=0; i<numSteps; i++){
        calculateForces(p, f, m, gnumBodies);
        moveBodies(p, f, m, v, gnumBodies);
    }

    cout << "Time taken was " << (omp_get_wtime() - start)<< " s"<< endl;
}

