#include <stdio.h>
#include <stdlib.h>
#include <omp.h>
#include <string.h>


void matrix_multiply(int n, int m, int p, int **A, int **B, int **C) {
  int i,j,k,v;
  for (i = 0; i < n; i++) {
    for (j = 0; j < p; j++) {
      v = 0;
      for (k = 0; k < m; k++) {
        v += A[i][k] * B[k][j];
      }
      C[i][j] = v;
    }
  }
}

void show_matrix(int **M, int n, int m) {
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < m; j++) {
      printf("%d\t", M[i][j]);
    }
    printf("\n");
  }
  printf("\n");
}

void prepare_matrix_data(int **M, int n, int m) {
  for (int i = 0; i < n; i++) {
      for (int j = 0; j < m; j++) {
          M[i][j] = (i + 1) * (j + 1);
      }
  }
}

int **create_matrix(int n, int m) {
  int **M = malloc(n * sizeof(int *));

  for (int i = 0; i < n; i++) {
      M[i] = malloc(m * sizeof(int));
  }

  return M;
}

void free_matrix(int **M, int n, int m) {
  for (int i = 0; i < n; i++) {
      free(M[i]);
  }
  free(M);
}

int main(int argc, char *argv[]) {
  int csvMode = 0;
  int n = 1;
  int m = 1;
  int p = 1;
  int maxIteratios = 1000;

  if (argc > 1) {
    if(strcmp(argv[1], "csv") == 0) {
      csvMode = 1;
    }
  }

  if (argc == 5) {
    n = atoi(argv[2]);
    m = atoi(argv[3]);
    p = atoi(argv[4]);
    maxIteratios = n+1;
  }

  if(csvMode == 1) {
    printf("n,m,p,time[s]\n");
  }

  for ( ; n < maxIteratios; n++, m++, p++) {
    int **A;
    int **B;
    int **C;
    double start, end;

    A = create_matrix(n, m);
    prepare_matrix_data(A, n, m);

    B = create_matrix(m, p);
    prepare_matrix_data(B, m, p);

    C = create_matrix(n, p);

    start = omp_get_wtime();
    matrix_multiply(n, m, p, A, B, C);
    end = omp_get_wtime();

    if(csvMode == 1) {
      printf("%d,%d,%d,%f\n",n, m, p, end-start);
    } else {
      printf("Czas wykonania dla parametrow n=%d, m=%d, p=%d wynosi: %f sekund\n",
      n, m, p, end-start);

      printf("Macierz C (A * B):\n");
      show_matrix(C, n, p);
    }

    free_matrix(A, n, m);
    free_matrix(B, m, p);
    free_matrix(C, n, p);
