The following code calculates a dot product of 2 vectors. First vector: Complex int16_t Second vector: Complex float Output: Complex float typedef struct ComplexInt16
{
    int16_t Re;
    int16_t Im;
}ComplexInt16;

typedef struct ComplexFloat
{
    float Re;
    float Im;
}ComplexFloat;

void ScalarMultiply(ComplexInt16 *In, ComplexFloat *Ref, ComplexFloat *Out, uint32_t N)
{
    ComplexInt16 *pIn = In;
    ComplexFloat *pRef = Ref;
    ComplexFloat *pOut = Out;

    int16x4x2_t     VecIn;
    float32x4x2_t   VecRef;
    float32x4x2_t   VecRes;

    float32x4x2_t Res;
    int16x4_t ReIn, ImIn;
    float32x4_t ReRef, ImRef, ReInf32;
    float32x4_t ReRes, ImRes, ImInf32;

    for (int i = 0; i < N >> 2; i++)
    {
        VecIn = vld2_s16((int16_t *)pIn);  //val[0]=1,3,5,7  val[1]=2,4,6,8 
        VecRef = vld2q_f32((float*)pRef);

        ReIn = VecIn.val[0];
        ImIn = VecIn.val[1];

        ReRef = VecRef.val[0];
        ImRef = VecRef.val[1];

        ReInf32 = vcvtq_f32_s32(vmovl_s16(ReIn));
        ImInf32 = vcvtq_f32_s32(vmovl_s16(ImIn));

        Res.val[0] = vsubq_f32(
            vmulq_f32(ReInf32, ReRef),
            vmulq_f32(ImInf32, ImRef));

        Res.val[1] = vaddq_f32(
            vmulq_f32(ImInf32, ReRef),
            vmulq_f32(ReInf32, ImRef));

        //Store in destination
        vst2q_f32((float*)pOut, Res);

        pIn += 4;
        pRef += 4;
        pOut += 4;
    }
} In order to run this code on all available cores (4) in my arm64 target I modified the code: void ScalarMultiply(ComplexInt16 *In, ComplexFloat *Ref, ComplexFloat *Out, uint32_t N)
