    ComplexFloat *pOut = Out;

    int16x4x2_t     VecIn;
    float32x4x2_t   VecRef;
    float32x4x2_t   VecRes;

    float32x4x2_t Res;
    int16x4_t ReIn, ImIn;
    float32x4_t ReRef, ImRef, ReInf32;
    float32x4_t ReRes, ImRes, ImInf32;
    uint32_t Offset;

#pragma omp parallel private (Offset, VecIn, VecRef, ReIn, ImIn, ReRef, ImRef, ReInf32, ImInf32, Res)
    {
#pragma omp for
        for (int i = 0; i < N >> 2; i++)
        {
            Offset = i << 2;
            VecIn = vld2_s16((int16_t *)(pIn + Offset));  //val[0]=1,3,5,7  val[1]=2,4,6,8 
            VecRef = vld2q_f32((float*)(pRef + Offset));

            ReIn = VecIn.val[0];
            ImIn = VecIn.val[1];

            ReRef = VecRef.val[0];
            ImRef = VecRef.val[1];

            ReInf32 = vcvtq_f32_s32(vmovl_s16(ReIn));
            ImInf32 = vcvtq_f32_s32(vmovl_s16(ImIn));

            Res.val[0] = vsubq_f32(
                vmulq_f32(ReInf32, ReRef),
                vmulq_f32(ImInf32, ImRef));

            Res.val[1] = vaddq_f32(
                vmulq_f32(ImInf32, ReRef),
                vmulq_f32(ReInf32, ImRef));

            //Store in destination
            vst2q_f32((float*)(pOut + Offset), Res);

            //pIn += 4;
            //pRef += 4;
            //pOut += 4;
        }
    }
}

/********************************************************************/
int main(int argc, char *argv[])
{
    struct timespec Before, After;
    ComplexInt16 *pIn = (ComplexInt16 *)aligned_alloc(ALIGN_SIZE, N_CELLS *sizeof(ComplexInt16));
    ComplexFloat *pRef = (ComplexFloat *)aligned_alloc(ALIGN_SIZE, N_REF*sizeof(ComplexFloat));
    ComplexFloat *pOut = (ComplexFloat *)aligned_alloc(ALIGN_SIZE, N_CELLS *sizeof(ComplexFloat));
