I'm testing simple locks and critical sections in OpenMP using a simple program as an example.
'Based on two vectors A and B (of length N), find the product of nonzero values A[i] * B[i]'. My code: const int N = 1000000;
const int R = 50;

void fill(vector<int>& vec) {
    for (int i = 0; i < N; i++) {
        vec[i] = rand() % R;
    }
}


int main()
{
    srand(time(NULL));
    chrono::duration<int64_t, nano> time;

    vector <int> A(N);
    vector <int> B(N);
    fill(A);
    fill(B);

    int i = 0;
    unsigned long long int total = 1;

    cout << "\n\n* Locks: " << endl;
    total = 1;
    omp_lock_t lock;
    omp_init_lock(&lock);
    auto start = chrono::high_resolution_clock::now();

#pragma omp parallel for private(i)
    for (i = 0; i < N; i++)
    {
        if (A[i] + B[i] != 0) {
            omp_set_lock(&lock);
            total *= A[i] + B[i];
            omp_unset_lock(&lock);
        }
    }
    time = chrono::high_resolution_clock::now() - start;
    omp_destroy_lock(&lock);
    cout << "\nResult Ai + Bi: " << total;
    cout << "\nTime: " << time.count() << " ns";


    cout << "\n\n* Critical section: " << endl;
    total = 1;
    start = chrono::high_resolution_clock::now();

#pragma omp parallel for private(i)
    for (i = 0; i < N; i++)
    {
        if (A[i] + B[i] != 0) {
#pragma omp critical
            total *= A[i] + B[i];
        }
    }
    time = chrono::high_resolution_clock::now() - start;

    cout << "\nResult Ai + Bi: " << total;
    cout << "\nTime: " << time.count() << " ns";
} I measured the time in nanoseconds and it turned out that the critical section works a little faster than the lock. Why, if they actually do the same thing? Visual Studio 2022, Windows 11

