    } );
    std::cout << whichThread << '\n';

    std::cout << "Inside parallel region:\n";
    #pragma omp parallel
    {
        inParallel( [&](int i){
            whichThread[i] = omp_get_thread_num();
        } );
    }
    std::cout << whichThread << '\n';

    return 0;
} So my question is: is there another way to achieve the same result but without the code duplication? For example, so that OpenMP effectively ignores the 'parallel' clause if in a parallel region? Other solutions that lead to minimal code duplication are equally welcome. EDIT: I tried omp_set_nested(true) before, which lead to a segfault. That's why I even posted the question. Now I managed to reproduce it, though the logic is slightly different: #include <iostream>
