    // Added an omp pragma directive to parallelize the loop with ncores
    #if defined(_OPENMP)
        #pragma omp parallel for num_threads(ncores)
    #endif
    for(arma::uword i = 0; i < ts2.size(); i++) {
        t = ts2(i);
        temp1 = dat.rows(find(dat.col(4) < t && dat.col(5) >= t));
        res1(i) = sum(1/temp1.col(6));
        temp2 = dat.rows(find(dat.col(3) == j && dat.col(2) == h));
        temp2a = temp2.rows(find(temp2.col(5) == t));
        res2(i) = sum(1/temp2a.col(6));
    }
    A.subvec(1,nn) = cumsum(res2/res1); 

    List res; 
    res["ts"] = ts2;
    res["A"] = A;
    return(res);
} The code is saved as case1.cpp. The function is called in R via Sys.setenv("PKG_CXXFLAGS" = "-fopenmp")
