answers.body:
Faster and fully optimizable, flush variable m before each if statement. // to compile: gcc -fopenmp -O* ping_pong.c
// * can be 0, 1, 2, 3, or fast
// to run: ./a.out -N 10000000

#include <assert.h>
#include <omp.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char **argv) {
  int num_threads = 2;
  int N = 1000000;

  for (int i = 1; i < argc; i++) {
    if (strcmp(argv[i], "-N") == 0) {
      N = atoi(argv[++i]);
    }
  }

  omp_set_num_threads(num_threads);

  int m = 0;

  int count0 = 0;
  int count1 = 0;
  int *arr0 = (int *)calloc(N / 2 + 2, sizeof(int));
  int *arr1 = (int *)calloc(N / 2 + 2, sizeof(int));

  double t0 = omp_get_wtime();
  #pragma omp parallel
  {
    int id = omp_get_thread_num();
    if (id == 0) {
      printf("id %d reporting for duty!\n", id);
      while (m < N) {
        #pragma omp flush (m)
        if (m % 2 == 0) {
          arr0[count0] = m;
          m++;
          count0++;
        }
      }
    }
    else if (id == 1) {
      printf("id %d reporting for duty!\n", id);
      while (m < N) {
        #pragma omp flush (m)
        if (m % 2 == 1) {
          arr1[count1] = m;
          m++;
          count1++;
        }
      }
    }
  }
  double t = omp_get_wtime() - t0;
  printf("done in %g secs, m: %d, count0: %d, count1: %d\n", t, m, count0, count1);

  for (int i = 1; i < N / 2; i++) {
    if (arr0[i] != arr0[i - 1] + 2) {
      printf("arr0[%d] = %d, arr0[%d] = %d\n", i, arr0[i], i - 1, arr0[i - 1]);
      assert(0);
    }
  }

  for (int i = 1; i < N / 2; i++) {
    if (arr1[i] != arr1[i - 1] + 2) {
      printf("arr1[%d] = %d, arr1[%d] = %d\n", i, arr1[i], i - 1, arr1[i - 1]);
      assert(0);
    }
  }

  printf("Both arrays are correctly formed.\n");

  free(arr0);
  free(arr1);

  return 0;
}

