string parameters = string.Format("{0} {1} {2}", cmdLineParam1, cmdLineParam2, cmdLineParam3);

Process process = new Process();
process.StartInfo = new ProcessStartInfo()
{
    Arguments = parameters,
    CreateNoWindow = true,
    FileName = pathToExe,
    WindowStyle = ProcessWindowStyle.Hidden
};

process.Start();

try
{
    // try to run this process on one dedicated CPU
    if (affinity > 0)
        process.ProcessorAffinity = new IntPtr(affinity);
}
catch (Exception e)
{
    Console.WriteLine("Could not set process affinity: {0}", e.Message);
}

// limit run-time of the process
if (process.WaitForExit(90000) == false)
{
    process.Kill();
    Console.WriteLine("Process has ran longer than 90 seconds, timing it out now.");
} Note that if you run this code across multiple threads, like I am doing, you will need to set a separate affinity for each thread, so that they'll use different CPU cores. Also note that affinity is a bitmask...This means that the number 3 indicates that a process should run on CPU cores 1 and 2, not core 3. to help with generating the bitmask, I wrote the code below: public static int GetProcessorBitMask(int numProcessors, int startingProcessor)
{
    Console.WriteLine("numProcessors: {0}  |  startingProcessor: {1}", numProcessors, startingProcessor);
    int mask = (int) Math.Pow(2, numProcessors) - 1;
    mask <<= (startingProcessor - 1);
    return mask;
}

